import React,{Component,useEffect,useMemo,useRef,useState} from 'react';
import {createRoot} from 'react-dom/client';
import {LayoutDashboard,BriefcaseBusiness,Users,Kanban,FileSearch,Activity,Settings,Search,RefreshCw,ExternalLink,Copy,CheckCircle2,Clock3,ShieldCheck,Menu,X} from 'lucide-react';
import './styles.css';
